DELIMITER $$
CREATE PROCEDURE sp_request_leave(IN p_faculty INT UNSIGNED,IN p_type INT UNSIGNED,IN p_start DATE,IN p_end DATE,IN p_days DECIMAL(5,2))
BEGIN IF p_end<p_start OR p_days<=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid leave period'; END IF; IF NOT EXISTS(SELECT 1 FROM faculty WHERE faculty_id=p_faculty AND status='ACTIVE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active faculty required'; END IF; INSERT INTO leave_request(faculty_id,leave_type_id,start_date,end_date,days_requested) VALUES(p_faculty,p_type,p_start,p_end,p_days); SELECT LAST_INSERT_ID() leave_request_id; END$$
CREATE PROCEDURE sp_approve_leave(IN p_request INT UNSIGNED,IN p_approve TINYINT)
BEGIN DECLARE v_faculty INT UNSIGNED; DECLARE v_type INT UNSIGNED; DECLARE v_days DECIMAL(5,2); DECLARE v_year SMALLINT; DECLARE v_status VARCHAR(10); DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; START TRANSACTION; SELECT faculty_id,leave_type_id,days_requested,YEAR(start_date),status INTO v_faculty,v_type,v_days,v_year,v_status FROM leave_request WHERE leave_request_id=p_request FOR UPDATE; IF v_status<>'PENDING' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Leave request is not pending'; END IF; IF p_approve=1 THEN UPDATE leave_balance SET days_remaining=days_remaining-v_days WHERE faculty_id=v_faculty AND leave_type_id=v_type AND balance_year=v_year AND days_remaining>=v_days; IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Insufficient leave balance'; END IF; UPDATE leave_request SET status='APPROVED',decided_at=NOW() WHERE leave_request_id=p_request; ELSE UPDATE leave_request SET status='REJECTED',decided_at=NOW() WHERE leave_request_id=p_request; END IF; COMMIT; SELECT p_request leave_request_id; END$$
CREATE PROCEDURE sp_generate_payroll(IN p_faculty INT UNSIGNED,IN p_start DATE,IN p_end DATE,IN p_lop DECIMAL(10,2))
BEGIN DECLARE v_basic DECIMAL(10,2); DECLARE v_gross DECIMAL(10,2); IF p_end<p_start OR p_lop<0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid payroll period or loss of pay'; END IF; SELECT basic_pay INTO v_basic FROM salary_structure WHERE faculty_id=p_faculty AND effective_from<=p_end AND (effective_to IS NULL OR effective_to>=p_start) ORDER BY effective_from DESC LIMIT 1; IF v_basic IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='No salary structure for period'; END IF; SET v_gross=v_basic*1.20; INSERT INTO payroll(faculty_id,period_start,period_end,basic_pay,gross_pay,pf_amount,professional_tax,lop_amount,net_pay) VALUES(p_faculty,p_start,p_end,v_basic,v_gross,v_basic*.12,200,p_lop,fn_payroll_net(v_basic,p_lop)); SELECT LAST_INSERT_ID() payroll_id; END$$
DELIMITER ;
